void qs_minmax(const double *v, size_t n, double *lo, double *hi)
{
    if (n == 0) {
        *lo = *hi = 0.0;
        return;
    }
    double a = v[0], b = v[0];
    for (size_t i = 1; i < n; i++) {
        if (v[i] < a)
            a = v[i];
        if (v[i] > b)
            b = v[i];
    }
    *lo = a;
    *hi = b;
}
